// ahead=false: what startup waits for (current form, playable stories, layers open now); ahead=true: also the next layer,
// warmed in the background after startup, where a failure never blocks play.
function warmReachableAssets(ahead=false){if(!globalThis.GameAssets?.preload)return Promise.resolve();const out=imagePaths(C.characters[s.active]);if(memoryUnlocked())out.add('assets/alice.png');for(const t of Object.values(C.stories)){if(t.retired||t.campaignChapter>1||C.characters[t.owner]?.chapter>1)continue;const form=R.storyForm(t.key)||s.active;if(!s.owned[form]||!R.canPlayStory({...s,active:form},t.key))continue;for(const path of storyImages(t,form))out.add(path);}for(const id of C.dungeonOrder)if(R.dungeonOpen(s,id)){imagePaths(C.dungeons[id],out);if(C.explorations?.[id])explorationImages(id,out,ahead);else for(const enemy of C.dungeons[id].enemies)imagePaths(C.enemies[enemy],out);}imagePaths(C.explorationIcons||{},out);for(const id of EXPLORATION_ICON_CATEGORIES.categories)out.add('assets/exploration/categories/'+id+'.webp');return GameAssets.preload([...out]);}
function scheduleAssetWarm(){const ready=globalThis.GamePresentationReady;if(!ready)return;const key=[s.active,s.view,s.dungeon,Object.keys(s.owned).join(','),Object.keys(s.completedStories).join(','),Object.keys(s.bosses).join(','),C.dungeonOrder.map(id=>C.explorations?.[id]?clearedLayers(id):'').join(',')].join('|');if(key===assetWarmKey)return;assetWarmKey=key;ready.then(()=>warmReachableAssets(true)).catch(()=>{assetWarmKey='';});}
function playStory(key,done=null,replay=false){if(memoryActive())return;const t=C.stories[key];if(!t||(!replay&&s.seen[key])){if(done)done();return;}if(story||preparingStory||!R.canPlayStory(s,key))return;if(!globalThis.GameAssets?.preload){openPreparedStory(key,done,replay);return;}advanceNow();preparingStory={key};notice='画像を読み込み中…';render();const appearance=R.storyForm(key)||s.active;GameAssets.preload(storyImages(visibleStory(t),appearance)).then(()=>{preparingStory=null;notice='';lastAt=Date.now();openPreparedStory(key,done,replay);},()=>{preparingStory=null;lastAt=Date.now();storyRetryAfter=Date.now()+5000;notice='画像を読み込めませんでした。通信を確認して、もう一度開いてください。';render();});}
// Lines marked ifOwned/unlessOwned (academy completion, T8) follow who has been devoured; scenes move with the kept lines.
function visibleStory(t){if(!t?.lines?.some(l=>l[2]?.ifOwned||l[2]?.unlessOwned))return t;const keep=t.lines.map(l=>!(l[2]?.ifOwned&&!s.owned[l[2].ifOwned])&&!(l[2]?.unlessOwned&&s.owned[l[2].unlessOwned])),before=i=>keep.slice(0,i).filter(Boolean).length;return {...t,lines:t.lines.filter((_,i)=>keep[i]),...(t.scenes?{scenes:t.scenes.map(sc=>({...sc,from:before(sc.from)}))}:{})};}
function openPreparedStory(key,done=null,replay=false){const t=visibleStory(C.stories[key]);if(!t||(!replay&&s.seen[key])){if(done)done();return;}if(story)return;advanceNow();if(!R.canPlayStory(s,key))return;const appearance=R.storyForm(key)||(replay?(s.storyForms[key]||s.active):s.active);R.markStory(s,key);story={key,t,index:0,done,appearance};lastAt=Date.now();paintStory();$('story').showModal();save();render();}
function paintStory(){if(!story)return;const lines=story.t.lines||[],original=lines[story.index]||['',''],line=DialogueSystem.line(original,story.appearance),face=DialogueSystem.face(line);$('storyTitle').textContent='';$('storyTitle').hidden=true;$('speaker').textContent=line[0];$('storyText').textContent=line[1];const scene=storyScene(story.t,story.index),sceneImg=$('storyScene');if(sceneImg){sceneImg.hidden=!scene;if(scene&&sceneImg.getAttribute('data-scene')!==scene.src){sceneImg.setAttribute('data-scene',scene.src);setImage(sceneImg,scene.src);sceneImg.alt=scene.alt||'';PortraitViewer.bind(sceneImg,scene);}}$('storyPortraitWrap').hidden=!face;$('story').classList.toggle('has-portrait',!!face);DialogueSystem.paint($('storyPortrait'),face);$('storyPage').textContent=(story.index+1)+' / '+lines.length;$('storyNext').textContent=story.index>=lines.length-1?'閉じる':'次へ →';$('story').scrollTop=0;}
